def f(a: int, b: int) -> int:
    """Returns the count of numbers in [min(a,b), max(a,b)] that contain the digit '1' exactly once in their absolute value."""
    lower, upper = min(a, b), max(a, b)
    count = 0
    for num in range(lower, upper + 1):
        s = str(abs(num))
        if s.count('1') == 1:
            count += 1
    return count

